mapper.select:
/*selectMasterMpIvDeliveryDateList*/ SELECT C.COM_NAME_LOC AS BUYER_NAME , B.BUYER , B.PO_NO , B.PO_SEQ , A.REVISION , C.BYCA_COMORG_CODE , B.CONTRACT_NO , B.CONTRACT_SEQ , B.BUYER_ITEM_NO , B.DESCRIPTION , B.SPECIFICATION , B.ITEM_QTY , B.IV_QTY , B.GR_QTY , B.DI_QTY , A.BEFORE_DATA , A.AFTER_DATA , A.ADD_DATE , A.CONFIRM_DATE , B.LEGACY_PO_NO , B.LEGACY_PO_SEQ , D.AGENT , (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = D.AGENT) AGENT_NAME , A.CONFIRM_ID , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.CONFIRM_ID) CONFIRM_USER_NM FROM ICOMPODT_MNG A, ICOMPODT B, ICOMCMPY C, ICOMPOHD D WHERE A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND B.BUYER = D.BUYER AND B.PO_NO = D.PO_NO AND A.BUYER = C.COM_CODE AND B.STATUS != 'D' AND A.STATUS = 'C' AND A.COLUMN_NM = 'RD_DATE' AND A.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER = #{st_buyer_code}
AND D.AGENT = #{st_agent_code}
AND A.PO_NO LIKE UPPER(#{st_po_no}||'%')
AND B.LEGACY_PO_NO LIKE UPPER(#{st_legacy_po_no}||'%')
AND B.BUYER_ITEM_NO LIKE UPPER(#{st_buyer_item_no}||'%')
AND A.CONFIRM_DATE IS NULL
ORDER BY C.COM_NAME_LOC, B.PO_NO

mapper.update:

/*updateMasterMpIvDeliveryDateList*/
UPDATE ICOMPODT_MNG
SET 
	  CONFIRM_FLAG = 'Y'
	  , CONFIRM_ID = #{st_user_id}
	  , CONFIRM_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
	  , CONFIRM_TIME =  TO_CHAR(SYSDATE, 'HH24MISS')         
WHERE
		BUYER	= #{BUYER}
	AND PO_NO	= #{PO_NO}
	AND PO_SEQ	= #{PO_SEQ}
	AND REVISION = #{REVISION}
